#pragma once
#include <unistd.h>
int runSaveAB(const char* methodText,const char* countText,const char* phaseText){
 const bool old=juce::String(methodText)=="old";const int count=juce::String(countText).getIntValue();const juce::String phase(phaseText);const bool sharing=phase=="sharing"||phase=="both",browser=phase=="browser"||phase=="both";
 if((!old&&juce::String(methodText)!="new")||(count!=0&&count!=600)||!(phase=="base"||phase=="sharing"||phase=="browser"||phase=="both"))return 3400;
 auto folder=juce::File::getCurrentWorkingDirectory().getChildFile("work/save-ab").getChildFile(juce::String(methodText)+"-"+juce::String(count)+"-"+phase);folder.deleteRecursively();folder.createDirectory();setenv("SLICE_GROUPS_LIBRARY",folder.getFullPathName().toRawUTF8(),1);LibraryStore::diagnosticOldSave=old;LibraryStore::diagnosticSharing=sharing;juce::ScopedJuceInitialiser_GUI gui;
 auto samples=folder.getChildFile("Samples");samples.createDirectory();auto prototype=std::make_shared<AudioData>();prototype->rate=12000;prototype->buffer.setSize(1,24000);prototype->buffer.clear();prototype->path=samples.getChildFile("test_00000.wav").getFullPathName();prototype->contentHash="benchmark-current";prototype->buildWaveformPeaks();if(!writeRenderedAudio(juce::File(prototype->path),prototype->buffer,prototype->rate))return 3401;
 const int files=5000;for(int i=1;i<files;++i){auto name=samples.getChildFile("test_"+juce::String(i).paddedLeft('0',5)+".wav");if(::link(prototype->path.toRawUTF8(),name.getFullPathName().toRawUTF8())!=0)return 3402;}
 Processor p(false);p.audio=prototype;p.trackOffline=true;p.split(64,false);p.normaliseEnabled=false;auto xml=p.configurationXml()->toString();auto values=juce::var(new juce::DynamicObject()),index=juce::var(new juce::DynamicObject());
 for(int i=0;i<count;++i){auto file=samples.getChildFile("test_"+juce::String(i).paddedLeft('0',5)+".wav");auto hash="benchmark-"+juce::String(i);auto config=juce::parseXML(xml);config->setAttribute("file",file.getFullPathName());config->setAttribute("contentHash",hash);auto text=config->toString();if(old){values.getDynamicObject()->setProperty(file.getFullPathName(),text);values.getDynamicObject()->setProperty("sha256:"+hash,text);}else{for(auto key:{"path:"+file.getFullPathName(),"sha256:"+hash}){auto target=LibraryStore::loopConfigFile(key);target.getParentDirectory().createDirectory();target.replaceWithText(text);}index.getDynamicObject()->setProperty(file.getFullPathName(),-1);}}
 if(old)LibraryStore::root().getChildFile("loops.json").replaceWithText(juce::JSON::toString(values));else LibraryStore::root().getChildFile("loop-index-v2.json").replaceWithText(juce::JSON::toString(index));LibraryStore::addLibraryRoot(samples);
 auto now=[](){return juce::Time::getMillisecondCounterHiRes();};auto pump=[](double seconds){CFRunLoopRunInMode(kCFRunLoopDefaultMode,seconds,true);};
 if(sharing&&count){auto end=now()+60000;bool ready=false;while(now()<end){auto snapshot=LibraryStore::sharedSnapshot("loops.json");if(auto* object=snapshot.getDynamicObject())if(object->getProperties().size()>=count){ready=true;break;}pump(.01);}if(!ready)return 3403;}
 std::unique_ptr<Editor> editor;double browserOpen=0;if(browser){auto start=now();editor=std::make_unique<Editor>(p);editor->diagnosticQuietAnalysis();editor->navigateForCheck(samples);editor->diagnosticQuietAnalysis();auto end=now()+30000;while(!editor->indexReadyForCheck()&&now()<end)pump(.01);if(!editor->indexReadyForCheck())return 3404;browserOpen=now()-start;}
 struct Heartbeat:juce::Timer{double last=0,maximum=0;bool measuring=false;void timerCallback()override{double current=juce::Time::getMillisecondCounterHiRes();if(measuring&&last>0)maximum=juce::jmax(maximum,current-last);last=current;}} heartbeat;heartbeat.startTimer(5);for(int i=0;i<20;++i)pump(.01);heartbeat.measuring=true;heartbeat.last=now();
 std::vector<double> queueTimes,finishTimes,keyTimes;for(int trial=0;trial<10;++trial){p.setPitch(trial*.1);auto completed=p.manualSaveCompleted.load();auto start=now();if(!p.queueAutoSave(false,true))return 3405;queueTimes.push_back(now()-start);double end=now()+30000;while(p.manualSaveCompleted.load()==completed&&now()<end)pump(.005);if(p.manualSaveCompleted.load()==completed||!p.manualSaveOK)return 3406;finishTimes.push_back(now()-start);auto settle=now()+100;while(now()<settle)pump(.005);if(editor)for(auto text:{"t","te","tes","test"}){auto begin=now();editor->diagnosticKeystroke(text);keyTimes.push_back(now()-begin);pump(.001);}}
 if(editor){
  editor->diagnosticKeystroke("test_00001");editor->diagnosticKeystroke("test_00002");
  auto until=now()+5000;while(now()<until&&(editor->browserRowsForCheck()!=1||editor->browserNameForCheck(0)!="test_00002.wav"))pump(.01);
  if(editor->browserRowsForCheck()!=1||editor->browserNameForCheck(0)!="test_00002.wav")return 3407;
  editor->diagnosticKeystroke("");until=now()+5000;while(now()<until&&editor->browserRowsForCheck()!=files)pump(.01);
  if(editor->browserRowsForCheck()!=files)return 3408;
 }
 heartbeat.measuring=false;heartbeat.stopTimer();auto summary=[](std::vector<double> v){auto result=juce::var(new juce::DynamicObject());if(v.empty())return result;std::sort(v.begin(),v.end());result.getDynamicObject()->setProperty("median_ms",v[v.size()/2]);result.getDynamicObject()->setProperty("max_ms",v.back());return result;};auto result=juce::var(new juce::DynamicObject());auto* out=result.getDynamicObject();out->setProperty("method",methodText);out->setProperty("saved_records",count);out->setProperty("phase",phase);out->setProperty("browser_files",files);out->setProperty("configuration_bytes",(juce::int64)xml.getNumBytesAsUTF8());out->setProperty("legacy_bytes",folder.getChildFile("loops.json").getSize());out->setProperty("queue",summary(queueTimes));out->setProperty("save_to_completion",summary(finishTimes));out->setProperty("keystroke",summary(keyTimes));out->setProperty("ui_max_gap_ms",heartbeat.maximum);out->setProperty("browser_open_ms",browserOpen);auto report=folder.getChildFile("result.json");report.replaceWithText(juce::JSON::toString(result));std::cout<<juce::JSON::toString(result,true)<<"\n";editor.reset();return 0;
}
